import{_ as o,C as t,o as r,c as i,E as a,a2 as d}from"./chunks/framework.VWKgVqrc.js";const c="/joinwell52/assets/boundaryxp-cycle-20261114/boundaryxp-eight-questions.en.svg",l="/joinwell52/assets/boundaryxp-cycle-20261114/boundaryxp-cycle.en.svg",h="/joinwell52/assets/boundaryxp-cycle-20261114/boundaryxp-workbench.en.jpg",k=JSON.parse(`{"title":"BoundaryXP: Make an AI Team’s Task Boundaries Visible","description":"Agents plan steps, use tools, and delegate work. Their plans can also expand beyond the task they were given. BoundaryXP uses 7+1 to organize requirements and mathematical methods to check budgets, permissions, ordering, and relationships across tasks.","frontmatter":{"schema":"publication-candidate-article/v2","title":"BoundaryXP: Make an AI Team’s Task Boundaries Visible","date":"2026-11-14","published_date":"2026-11-14","updated_date":"2026-11-16","column":"open-source-engineering","category":"daily","article_type":"project-research","edition":"research-center","research_question":"How can natural-language requirements become inspectable boundaries for checking an agent's plans and subtasks?","summary":"Agents plan steps, use tools, and delegate work. Their plans can also expand beyond the task they were given. BoundaryXP uses 7+1 to organize requirements and mathematical methods to check budgets, permissions, ordering, and relationships across tasks.","description":"Agents plan steps, use tools, and delegate work. Their plans can also expand beyond the task they were given. BoundaryXP uses 7+1 to organize requirements and mathematical methods to check budgets, permissions, ordering, and relationships across tasks.","cover":"/assets/boundaryxp-cycle-20261114/boundaryxp-radar.en.cover-v7.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Public saved cases and research materials; selected mathematical checks from 2026-11-14 retained; protocol and rc.9 release notes checked on 2026-11-16, with no new model runs","sources":["https://doi.org/10.5281/zenodo.24072738","https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/protocol/versions/0.4.0-draft.2/BXP-0001.md","https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/paper/materials/analysis625/REPORT.zh-CN.md","https://github.com/joinwell52-AI/BoundaryXP/releases/tag/mcp-v0.4.0-rc.9"],"pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-14-boundaryxp-local-global-cycle.md","filePath":"en/research/2026-11-14-boundaryxp-local-global-cycle.md","lastUpdated":1794818231000}`),p={name:"en/research/2026-11-14-boundaryxp-local-global-cycle.md"};function u(m,e,b,g,f,y){const n=t("ArticleCover"),s=t("ArticleTableScroll");return r(),i("div",null,[a(n,{image:"/assets/boundaryxp-cycle-20261114/boundaryxp-radar.en.cover-v7.png",kicker:"Project research · AI task boundaries",title:"BoundaryXP: Make an AI Team’s Task Boundaries Visible",summary:"Agents plan steps, use tools, and delegate work. Their plans can also expand beyond the task they were given. BoundaryXP uses 7+1 to organize requirements and mathematical methods to check budgets, permissions, ordering, and relationships across tasks.",version:"Published 2026-11-14 · Revised 2026-11-16",languageHref:"/zh/research/2026-11-14-boundaryxp-local-global-cycle",languageLabel:"中文"}),a(s,{language:"en"}),e[0]||(e[0]=d('<h1 id="boundaryxp-make-an-ai-team-s-task-boundaries-visible" tabindex="-1">BoundaryXP: Make an AI Team’s Task Boundaries Visible <a class="header-anchor" href="#boundaryxp-make-an-ai-team-s-task-boundaries-visible" aria-label="Permalink to &quot;BoundaryXP: Make an AI Team’s Task Boundaries Visible&quot;">​</a></h1><p>Suppose you give a team of AI agents this assignment:</p><blockquote><p>Review the maintenance records for these vehicles, identify anything unusual, and deliver a report. Read the records only; do not change the system.</p></blockquote><p>During the work, one agent spots an obvious error and proposes changing the database. Another wants to download an attachment and hand it to a teammate writing the report. Pause before giving both actions the same verdict: <strong>changing the database conflicts with “do not change the system”; whether downloading the attachment is permitted depends on the stated information scope, storage location, and handling rules.</strong></p><p>More difficult still: what if subtasks add their own ordering rules, each workable on its own, but forming a cycle when combined? Where does that conflict belong? Was the parent task unclear, or do the added subtask requirements conflict only when brought together? Intuition alone makes these questions hard to answer consistently or trace back to the assignment.</p><p>BoundaryXP aims to make task boundaries inspectable and open to discussion, with each judgment linked to its source. Its <strong>7+1 method for task boundary verification</strong> organizes eight classes of requirements and their relationships, then uses mathematical checks on the parent task, subtasks, and their combined plan. The <a href="https://doi.org/10.5281/zenodo.24072738" target="_blank" rel="noreferrer">method paper</a> and <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/protocol/versions/0.4.0-draft.2/BXP-0001.md" target="_blank" rel="noreferrer">draft protocol</a> are public.</p><h2 id="why-is-stating-the-goal-not-enough" tabindex="-1">Why is stating the goal not enough? <a class="header-anchor" href="#why-is-stating-the-goal-not-enough" aria-label="Permalink to &quot;Why is stating the goal not enough?&quot;">​</a></h2><p>Agents can plan steps, call tools, and delegate work in pursuit of a goal. Beyond the desired outcome, a task must say which information may be used, which actions are allowed, who can confirm the result, how much may be spent, and what is forbidden. An account&#39;s ability to perform an operation does not mean <strong>this assignment authorizes it</strong>.</p><p>These requirements define a <strong>task boundary</strong>: what must be done, which approaches are acceptable, which conditions remain unmet, and what must not happen in this assignment. When work is divided among several agents, the applicable requirements must continue to constrain each proposed subtask and the combined plan.</p><h2 id="_7-1-starts-with-eight-questions-about-the-task" tabindex="-1">7+1 starts with eight questions about the task <a class="header-anchor" href="#_7-1-starts-with-eight-questions-about-the-task" aria-label="Permalink to &quot;7+1 starts with eight questions about the task&quot;">​</a></h2><p>A task specification often puts objectives, permissions, budgets, and acceptance requirements into the same paragraph. The 7+1 representation gives these requirements a place: seven task views, plus a separate view for explicit prohibitions.</p><table tabindex="0"><thead><tr><th>View</th><th>Questions to clarify</th></tr></thead><tbody><tr><td><strong>I · Input scope</strong></td><td>Which information, systems, and objects may be used? Where does the scope end?</td></tr><tr><td><strong>O · Outputs</strong></td><td>What must be delivered, and to whom?</td></tr><tr><td><strong>A · Actions</strong></td><td>What must be done, what may be done, and to which objects?</td></tr><tr><td><strong>P · Responsibilities and division of work</strong></td><td>Who executes, reviews, approves, and receives the work?</td></tr><tr><td><strong>R · Resources</strong></td><td>What are the limits on budget, time, capacity, and quantity?</td></tr><tr><td><strong>V · Version and basis</strong></td><td>Which rules, policies, or evidence govern the task? Which versions and time references apply?</td></tr><tr><td><strong>C · Completion and stopping</strong></td><td>What counts as completion? When must work stop or be escalated?</td></tr><tr><td><strong>B · Independent prohibition boundary</strong></td><td>Which actions, targets, or effects are explicitly forbidden? What conditions and exceptions are stated?</td></tr></tbody></table><figure><img src="'+c+'" alt="The eight 7+1 directions cover inputs, outputs, actions, responsibilities, resources, version and basis, completion and stopping, and prohibitions; each identifies questions to clarify in a task"><figcaption>The eight directions organize task requirements. The outline identifies views, not scores; individual clauses must also be connected through their objects, conditions, and source evidence.</figcaption></figure><p>In the vehicle example, “the maintenance records for these vehicles” establishes the input scope, the report is an output, reviewing is an action, and “do not change the system” remains an explicit prohibition. If the task does not name the report&#39;s recipient, that gap should remain visible. The system should not invent a recipient on the task owner&#39;s behalf. Nor should every empty view automatically count as a failure: the question is whether the missing information affects this particular judgment.</p><p><strong>Listing eight views is a beginning. The relationships among requirements matter just as much.</strong> When two teams mention a budget, do they mean the same pool of money? In “release only after acceptance,” which version must be accepted? Does “device one” in a subtask identify the same device as in the parent task? These relationships determine what the calculation actually checks.</p><p>L2 industry dictionaries and L3 enterprise dictionaries can help resolve domain terms and local names. For example, a shorthand name may refer to either a test environment or a production environment; the interpretation needs evidence. A dictionary explanation or job title does not itself add authority. The <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/protocol/versions/0.4.0-draft.2/BXP-0001.md" target="_blank" rel="noreferrer">protocol&#39;s definitions of views and shared relationships</a> and the <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/mcp/TOOLS.md" target="_blank" rel="noreferrer">dictionary tool reference</a> set out these conventions.</p><h2 id="decide-first-if-each-group-s-plan-works-will-the-combination-work" tabindex="-1">Decide first: if each group&#39;s plan works, will the combination work? <a class="header-anchor" href="#decide-first-if-each-group-s-plan-works-will-the-combination-work" aria-label="Permalink to &quot;Decide first: if each group&#39;s plan works, will the combination work?&quot;">​</a></h2><p>BoundaryXP&#39;s public <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/demo/reports/R389-383.en.md" target="_blank" rel="noreferrer">RT044 saved case</a> illustrates a problem that emerges when tasks are combined. It is a laboratory planning example. Within the same round, safety review, equipment startup, packaging, and submission for testing each occur once.</p><p>The parent task and three groups specify the following orderings:</p><table tabindex="0"><thead><tr><th>Source</th><th>Ordering requirement</th></tr></thead><tbody><tr><td>Parent task</td><td>Safety review must finish before startup.</td></tr><tr><td>Test group</td><td>Startup must finish before packaging begins.</td></tr><tr><td>Laboratory group</td><td>Packaging must finish before submission for testing begins.</td></tr><tr><td>Safety group</td><td>Submission for testing must finish before this safety review begins.</td></tr></tbody></table><p>Before reading the result, try three questions: can each group&#39;s additional rule coexist with the parent task on its own? What happens when all four rules are combined? If there is a conflict, can we attribute an individual violation to just one group?</p><p><strong>Pause for a few seconds, or trace the arrows on paper, before reading on.</strong></p><h3 id="the-combined-result" tabindex="-1">The combined result <a class="header-anchor" href="#the-combined-result" aria-label="Permalink to &quot;The combined result&quot;">​</a></h3><p>Each group&#39;s additional ordering, <strong>checked separately against the parent</strong>, permits an arrangement that satisfies those requirements. Adding all three produces:</p><blockquote><p><strong>Safety review → startup → packaging → submission for testing → the same safety review.</strong></p></blockquote><figure><img src="'+l+`" alt="Safety review, equipment startup, packaging, and submission for testing in the same round form a strict prerequisite cycle: the parent puts review before startup, while the combined child requirements put that review after submission"><figcaption>Each child ordering can be added to the parent separately. Together they form a strict cycle. Letters in the diagram identify events in this case; the conflict belongs to the combined plan.</figcaption></figure><p>The mathematical contradiction is straightforward. Each event starts before it finishes, and the preceding event must finish before the next can start. Following these strict orderings around the loop produces a contradiction: the safety review would have to begin before it begins. No schedule can satisfy all the requirements.</p><p>The source fixes the events to the same round and occurrence. Adding an imagined second review or a different sample would change the problem. Someone authorized to revise the plan needs to preserve the parent requirement, adjust the ordering in the proposed subtasks, and check the result again.</p><p>This is why a team of agents needs a check of the whole plan. Local feasibility says only that the requirements in that local comparison can coexist. It does not replace a joint check. The finding here is a <strong>violation in the combined plan</strong>, supported by the requirements forming the cycle. It should not be recast as a separate violation by every group. Can you now explain your answer to the third question using all four source rules?</p><h2 id="from-words-to-mathematics-how-is-the-boundary-calculated" tabindex="-1">From words to mathematics: how is the boundary calculated? <a class="header-anchor" href="#from-words-to-mathematics-how-is-the-boundary-calculated" aria-label="Permalink to &quot;From words to mathematics: how is the boundary calculated?&quot;">​</a></h2><p>The 7+1 representation preserves eight classes of requirements together with shared objects, identities, scope, and conditions. Under a fixed interpretation, the <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/protocol/versions/0.4.0-draft.2/BXP-0001.md" target="_blank" rel="noreferrer">BXP protocol draft</a> defines the boundary as the set of candidate plans satisfying the constraints:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>χ_M(x) = Q(x) ∧ ¬F(x) ∧ K(x) ∧ Φ(x)</span></span>
<span class="line"><span>Ω_M    = {x ∈ X_Σ | χ_M(x) = true}</span></span></code></pre></div><p><code>Q</code> contains obligations, <code>F</code> forbidden states, <code>K</code> completion or stopping conditions, and <code>Φ</code> other constraints. <code>Ω_M</code> contains acceptable plans under that fixed interpretation. We need not enumerate every plan: we can test whether a particular plan belongs to <code>Ω_M</code>, or whether combining requirements leaves that set empty.</p><p><strong>Calculation one: local versus combined constraints in RT044.</strong> Let <code>A</code> be the safety review, <code>D</code> equipment startup, <code>B</code> packaging, and <code>C</code> submission for testing; subscripts <code>s/e</code> denote the planned start and end of each unique event in the same round. The <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/demo/reports/R389-383.en.md" target="_blank" rel="noreferrer">saved 7+1 report</a> formalizes the parent task and three subtasks as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P = (A_e &lt; D_s) ∧ ∧[X∈{A,B,C,D}](X_s &lt; X_e)</span></span>
<span class="line"><span>T = (D_e &lt; B_s)       TEST</span></span>
<span class="line"><span>L = (B_e &lt; C_s)       LAB</span></span>
<span class="line"><span>F = (C_e &lt; A_s)       SAFETY</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SAT(P) = true</span></span>
<span class="line"><span>SAT(P∧T) = SAT(P∧L) = SAT(P∧F) = true</span></span>
<span class="line"><span>SAT(P∧T∧L) = SAT(P∧T∧F) = SAT(P∧L∧F) = true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>P∧T∧L∧F ⇒ A_s &lt; A_e &lt; D_s &lt; D_e &lt; B_s &lt; B_e &lt; C_s &lt; C_e &lt; A_s</span></span>
<span class="line"><span>            ⇒ A_s &lt; A_s ⇒ false</span></span>
<span class="line"><span>SAT(P∧T∧L∧F) = false; Ω(P∧T∧L∧F) = ∅</span></span>
<span class="line"><span>Ω(P) ≠ ∅, but Ω(P∧T∧L∧F) = ∅ → combined plan violates the boundary</span></span></code></pre></div><p><code>SAT</code> asks whether any schedule satisfies all listed constraints. The report supplies endpoint witnesses for local feasibility and feasible orderings after any one child ordering is removed. <strong>Only the full combination empties the feasible set.</strong> This calculation concerns task specifications; it does not assert that the four events occurred.</p><p><strong>Calculation two: equipment occupancy and handoff in RT042.</strong> Another <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/demo/reports/R389-381.en.md" target="_blank" rel="noreferrer">saved 7+1 report</a> records planned occupancy of the same instrument <code>M</code> in minutes after midnight: <code>J_X=[600,660)</code> and <code>J_Y=[660,720)</code>. Substituting the half-open interval endpoints into the overlap test gives:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>overlap(X,Y) ⇔ max(s_X,s_Y) &lt; min(e_X,e_Y)</span></span>
<span class="line"><span>             ⇔ max(600,660) &lt; min(660,720)</span></span>
<span class="line"><span>             ⇔ 660 &lt; 660 = false</span></span>
<span class="line"><span>J_X ∩ J_Y = ∅; s_Y − e_X = 0</span></span></code></pre></div><p>The parent task explicitly permits release and immediate handoff at the shared endpoint, with cleanup included in each occupancy period. The report evaluates the <strong>stated handoff conditions</strong> separately: <code>r</code> means “released at 11:00,” <code>b</code> means “no residual occupancy,” and <code>n</code> means “no third concurrent reservation.” These truth values come from statements in the task text.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D = r ∧ b = true ∧ true = true       K5: stated condition supported</span></span>
<span class="line"><span>N = n     = true                    K6: stated condition supported</span></span>
<span class="line"><span>K1: planned occupancy of M does not overlap → within bounds</span></span></code></pre></div><p>K1 compares the <strong>plan</strong>; K5 and K6 check support for <strong>stated conditions</strong>. None proves that the instrument was actually operated, work was accepted, or execution was authorized. RT042 specifies no numeric budget; an invented budget sum would not be one of its calculations.</p><p>These results can be compared because the report retains the same events and instrument, the half-open endpoint convention, and the source clauses. If objects, negation, or scope remain ambiguous, a formula computes the result for <strong>one interpretation</strong>; it cannot by itself prove that the source text has been interpreted correctly and completely.</p><h2 id="what-do-violation-within-bounds-and-incomplete-information-mean" tabindex="-1">What do violation, within bounds, and incomplete information mean? <a class="header-anchor" href="#what-do-violation-within-bounds-and-incomplete-information-mean" aria-label="Permalink to &quot;What do violation, within bounds, and incomplete information mean?&quot;">​</a></h2><p>Boundary verification examines how a plan, or explicitly supplied facts about behavior, relates to the task requirements. Three cases in the public demo illustrate the distinction:</p><table tabindex="0"><thead><tr><th>Result and case</th><th>Basis for the judgment</th><th>What the finding establishes</th></tr></thead><tbody><tr><td><strong>Violation: RT044</strong></td><td>Strict ordering requirements for the same round form a cycle.</td><td>The current combined plan contains a definite conflict and needs revision.</td></tr><tr><td><strong>Within bounds: RT042</strong></td><td>One device is booked for 10–11 and 11–12. The rules explicitly release it at the endpoint, permit immediate handoff, and include cleanup time.</td><td>Under those conditions, the bookings do not overlap.</td></tr><tr><td><strong>Incomplete information: L23-050</strong></td><td>Lin Zhou and Zhao Qing both attend the meeting, but the task says only “he will confirm,” without identifying one person.</td><td>The final confirmer cannot be determined; the identity needs clarification.</td></tr></tbody></table><p>The RT042 substitution above gives <code>660 &lt; 660 = false</code>: the planned occupancies do not overlap. K5 and K6 separately check the stated release and no-third-reservation conditions; these results are not receipts of actual execution. <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/demo/reports/R389-381.en.md" target="_blank" rel="noreferrer">Full device-case calculation</a></p><p>In L23-050, material preparation and requests for clarification can continue, while the final confirmer still needs to be identified. A person&#39;s seniority cannot fill that gap on the task owner&#39;s behalf. Nor does the ambiguity establish that someone has already performed an unauthorized acceptance. <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/demo/reports/R389-153.en.md" target="_blank" rel="noreferrer">Responsibility case: source and calculation</a></p><p><strong>“Within bounds” applies to the requirements and evidence examined in that check.</strong> It does not establish that the work is complete, the output is correct, or business approval has been obtained. Unknown information also need not prevent every conclusion. If known expenses already exceed a limit and any remaining expenses can only add to the total, with no offsets, uncertainty about those amounts cannot remove the established excess.</p><h2 id="how-do-the-method-protocol-and-tool-support-one-another" tabindex="-1">How do the method, protocol, and tool support one another? <a class="header-anchor" href="#how-do-the-method-protocol-and-tool-support-one-another" aria-label="Permalink to &quot;How do the method, protocol, and tool support one another?&quot;">​</a></h2><p>The 7+1 method organizes task requirements and their relationships into a representation that supports comparison. The BXP protocol specifies how the representation, evidence, calculations, and results are handled. The BoundaryXP tool applies this process to concrete tasks and displays the source, analysis, calculation records, and unresolved questions. The draft protocol and the implementation have their own versions; the <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/protocol/IMPLEMENTATION.md" target="_blank" rel="noreferrer">implementation status</a> describes the current scope.</p><p>The <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/paper/materials/analysis625/REPORT.zh-CN.md" target="_blank" rel="noreferrer">public research materials</a> preserve <strong>625 task groups, 3,219 task nodes, and 3,469 queries</strong> involving logic, quantities, set identity, dependencies, and combined constraints. The final verdict in each of the 625 saved cases agrees with its current annotation; the saved model judgments at the whole-case level also agree with the program&#39;s aggregate results. Comparing individual queries still reveals <strong>nine differences between model judgments and program results</strong>: six label-encoding differences and three differences in calculation judgments. Another <strong>three calculations remain incomplete because specified inputs are missing</strong>. <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/paper/materials/evidence-r18/SOURCE-REPORT.md" target="_blank" rel="noreferrer">Counting rules and source records</a></p><p>These materials let readers inspect how the method applies to specific problems, how conflicts are located, and how unknown information affects a conclusion. Whole-case agreement measures the relationship between these saved records and the current annotations. It cannot be extrapolated into accuracy on unseen tasks.</p><p>The site&#39;s <a href="https://github.com/joinwell52-AI/joinwell52/blob/ac13a5f8fabe7bc1fc1aa71ded19c5666fbf3625/research/manual-runs/2026-11-14-boundaryxp/00-report.en.md" target="_blank" rel="noreferrer">November 14 verification record</a> also records digest and classification checks, six selected mathematical witnesses, and recomputation of nine calculations from one expense case. These were historical checks with a defined scope, without rerunning all model analyses. This revision retains that evidence and updates the product&#39;s integration information.</p><h2 id="how-can-you-inspect-a-report-and-analyze-your-own-task" tabindex="-1">How can you inspect a report and analyze your own task? <a class="header-anchor" href="#how-can-you-inspect-a-report-and-analyze-your-own-task" aria-label="Permalink to &quot;How can you inspect a report and analyze your own task?&quot;">​</a></h2><p>Start with the <a href="https://boundaryxp-workbench-demo.joinwell52.chatgpt.site/?lang=en#case=R389-383&amp;axis=A&amp;view=radar&amp;lang=en" target="_blank" rel="noreferrer">English interactive demo</a> and open RT044. Select a node in the task tree, choose a view, and inspect the relevant clauses and source passages. This shows which requirements support a particular conclusion.</p><figure><img src="`+h+'" alt="BoundaryXP&#39;s English demo workbench, with a parent-child task tree on the left, the 7+1 boundary radar in the center, and clauses, source text, and verification evidence on the right"><figcaption>The public workbench places the task tree, 7+1 views, and source evidence on one page. This English screenshot shows the separate ENG20-003 case. Both the screenshot and the online demo display saved cases; they do not run a fresh analysis of your task.</figcaption></figure><p>To analyze your own tasks, follow the <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/docs/mcp/npm/INSTALL.md" target="_blank" rel="noreferrer">MCP installation guide</a> to connect BoundaryXP to Cursor or Codex. As of November 16, 2026, the public prerelease is <strong>0.4.0-rc.9</strong> for Windows x64, with <strong>21 MCP tools, 17 resources</strong>, and a local browser workbench. The release adds format guidance, validation, and import for L2 industry and L3 enterprise custom dictionaries, helping teams check task specific terms and internal names. For installation and upgrades, see the guide and <a href="https://github.com/joinwell52-AI/BoundaryXP/releases/tag/mcp-v0.4.0-rc.9" target="_blank" rel="noreferrer">rc.9 release notes</a>. It can use the model in the current host without requiring a separate model API key; an independent API mode is also available. Host mode still uses a model. “No additional API key” does not mean that no model service is involved.</p><p>In use, import the complete parent task and subtasks, inspect the task tree, save it, and explicitly request analysis. The report keeps the model&#39;s interpretation and the calculation Core&#39;s checks of supported operands, so they can be inspected separately. Saved operands can also be recomputed without a new model call. Opening the workbench alone does not submit a fresh analysis. <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/4a843cd63b804cf2f0d3280e50689afca698d320/docs/mcp/TOOLS.md" target="_blank" rel="noreferrer">Tool responsibilities</a></p><p>Public materials currently include documentation, the protocol, the paper, research cases, and compiled installation packages. Original Core implementation source remains in a separate private repository. Reports also retain a scope: calculations verify the problem as represented, while the completeness and accuracy of the source interpretation still need checking. Plan changes, business approval, and execution remain with the responsible people or business systems.</p><h2 id="now-try-checking-a-boundary-yourself" tabindex="-1">Now try checking a boundary yourself <a class="header-anchor" href="#now-try-checking-a-boundary-yourself" aria-label="Permalink to &quot;Now try checking a boundary yourself&quot;">​</a></h2><p>When work goes to a team of agents, their plans must be brought back together to see whether shared requirements still hold. BoundaryXP aims to make that check specific: identify the requirement, the subtasks, and the calculation involved, so a person has something concrete to revise beyond an assurance that the plan looks feasible.</p><p>Start with a task of your own. Write down its input scope, outputs, actions, responsibilities, resources, version and basis, completion and stopping conditions, and prohibitions. Then ask: <strong>when all relevant subtasks are combined, does a conflict emerge that separate checks or pairwise comparisons would miss?</strong></p><p>There are further questions worth investigating. If a task does not specify where an attachment may be stored, which judgments should remain unknown? When an industry or enterprise dictionary changes, how should an old report preserve the meanings it used? If the combined plan conflicts, who may revise the order, and how can we show that the parent requirement was not silently altered? When might a stricter rule added by a subtask obstruct the shared delivery, and who may reject or revise it?</p><p>If a real constraint is hard to express, or you disagree with a saved case&#39;s judgment, bring a <strong>minimal task excerpt you are allowed to share</strong>, its version, and your specific question to the discussion. You can also open the demo, select a requirement on the radar, and trace the RT044 cycle back through its report to the source. <strong>A method becomes more dependable when its users can inspect and challenge it.</strong></p><p>The repository now offers focused participation routes: <a href="https://github.com/joinwell52-AI/BoundaryXP/issues/new?template=04-question.yml" target="_blank" rel="noreferrer">Questions and ideas</a> · <a href="https://github.com/joinwell52-AI/BoundaryXP/issues/new?template=01-method-counterexample.yml" target="_blank" rel="noreferrer">7+1 method counterexamples</a> · <a href="https://github.com/joinwell52-AI/BoundaryXP/issues/new?template=02-mcp-problem.yml" target="_blank" rel="noreferrer">MCP problems</a> · <a href="https://github.com/joinwell52-AI/BoundaryXP/issues/new?template=03-semantic-resource.yml" target="_blank" rel="noreferrer">L2/L3 semantic issues</a> · <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">Contributions and PRs</a>. Public issues and PRs should not include secrets, customer data, or private runtime logs.</p><p><a href="https://github.com/joinwell52-AI/BoundaryXP" target="_blank" rel="noreferrer">Explore the public repository and discuss</a> · <a href="https://doi.org/10.5281/zenodo.24072738" target="_blank" rel="noreferrer">Read the method paper</a> · <a href="https://boundaryxp-workbench-demo.joinwell52.chatgpt.site/?lang=en#case=R389-383&amp;axis=A&amp;view=radar&amp;lang=en" target="_blank" rel="noreferrer">Open the interactive demo</a> · <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/docs/mcp/npm/INSTALL.md" target="_blank" rel="noreferrer">Read the installation guide</a></p>',66))])}const v=o(p,[["render",u]]);export{k as __pageData,v as default};
